<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlySelfAccessibles
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(UserPersonalApiKeyRestrictFilterToVisibility $event): UserPersonalApiKeyRestrictFilterToVisibility
    {
        $this->logDebug("Check OnlySelfAccessibles User personal api key");
        $span = $this->startSpan("Check OnlySelfAccessibles User personal api key");
        try {
            $event->with($event->userPersonalApiKeyFilter->withOnlySelfAccessibles($identity->getUid()));
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
